/* Soft386 native VIO/KBD/SESMGR bridge.
 *
 * Guest pointers never cross into a native DLL.  Every buffer/string/structure
 * is copied into bounded host storage first, and output is copied back only
 * after guest-range validation.  The same marshal layer accepts normal 32-bit
 * cdecl frames and the packed C/386 Pascal frames generated by the migration
 * helper lowering pass.
 */
#include "soft386_system_bridge.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#endif

#ifndef __cdecl
#define __cdecl
#endif

#define OS2_NO_ERROR                 0u
#define OS2_ERROR_INVALID_FUNCTION   1u
#define OS2_ERROR_INVALID_HANDLE     6u
#define OS2_ERROR_NOT_ENOUGH_MEMORY  8u
#define OS2_ERROR_INVALID_PARAMETER 87u
#define BRIDGE_MAX_STRING          4096u
#define BRIDGE_MAX_BUFFER      0x01000000u
#define SES_TEXT_MAX               260u
#define SES_WIRE_SIZE              528u

/* Packed Pascal frame widths are ordered exactly as they appear at ESP+4:
 * rightmost argument first.  This table is intentionally kept in sync with
 * loader/os2host32.c's frozen C/386 descriptors. */
static const struct Soft386C386ApiDesc c386_apis[] = {
    /* Historical 16-bit DOSCALLS entry used by INCL_16 C/386 programs.
     * The helper is lowered to a 32-bit Soft386 hostcall, but DosSleep itself
     * remains jar-owned so it participates in virtual-thread scheduling. */
    {"DOSCALLS","DosSleep",32,1,{4,0,0,0,0,0,0}},
    {"VIOCALLS","VioScrollUp",7,7,{2,4,2,2,2,2,2}},
    {"VIOCALLS","VioGetCurPos",9,3,{2,4,4,0,0,0,0}},
    {"VIOCALLS","VioWrtCharStr",13,5,{2,2,2,2,4,0,0}},
    {"VIOCALLS","VioSetCurPos",15,3,{2,2,2,0,0,0,0}},
    {"VIOCALLS","VioWrtTTY",19,3,{2,2,4,0,0,0,0}},
    {"VIOCALLS","VioGetMode",21,2,{2,4,0,0,0,0,0}},
    {"VIOCALLS","VioReadCellStr",24,5,{2,2,2,4,4,0,0}},
    {"VIOCALLS","VioWrtNAttr",26,5,{2,2,2,2,4,0,0}},
    {"VIOCALLS","VioGetCurType",27,2,{2,4,0,0,0,0,0}},
    {"VIOCALLS","VioSetCurType",32,2,{2,4,0,0,0,0,0}},
    {"VIOCALLS","VioWrtCharStrAtt",48,6,{2,4,2,2,2,4,0}},
    {"VIOCALLS","VioWrtNCell",52,5,{2,2,2,2,4,0,0}},
    {"KBDCALLS","KbdCharIn",4,3,{2,2,4,0,0,0,0}},
    {"KBDCALLS","KbdStringIn",9,4,{2,2,4,4,0,0,0}},
    {"KBDCALLS","KbdGetStatus",10,2,{2,4,0,0,0,0,0}},
    {"KBDCALLS","KbdSetStatus",11,2,{2,4,0,0,0,0,0}},
    {"KBDCALLS","KbdFlushBuffer",13,1,{2,0,0,0,0,0,0}},
    {"KBDCALLS","KbdPeek",22,2,{2,4,0,0,0,0,0}}
};

static int eqi(const char *a, const char *b)
{
    unsigned char ca, cb;
    if (!a || !b) return 0;
    for (;;) {
        ca=(unsigned char)*a++; cb=(unsigned char)*b++;
        if (ca>='a'&&ca<='z') ca=(unsigned char)(ca-'a'+'A');
        if (cb>='a'&&cb<='z') cb=(unsigned char)(cb-'a'+'A');
        if (ca!=cb) return 0;
        if (!ca) return 1;
    }
}

uint32_t soft386_c386_desc_count(void)
{
    return (uint32_t)(sizeof(c386_apis)/sizeof(c386_apis[0]));
}
int soft386_c386_desc_index(const char *module, uint32_t ordinal)
{
    uint32_t i;
    for(i=0;i<soft386_c386_desc_count();++i)
        if(eqi(module,c386_apis[i].module)&&ordinal==c386_apis[i].ordinal)
            return (int)i;
    return -1;
}
const struct Soft386C386ApiDesc *soft386_c386_desc_by_id(uint32_t id)
{
    if(id==0 || id>soft386_c386_desc_count()) return NULL;
    return &c386_apis[id-1u];
}

#ifdef _WIN32
struct WinModule { HMODULE h; };
static void *win_get_proc(void *opaque,uint32_t ordinal)
{
    struct WinModule *m=(struct WinModule*)opaque; FARPROC p;
    if(!m||!m->h||ordinal>65535u)return NULL;
    p=GetProcAddress(m->h,(LPCSTR)(uintptr_t)(uint16_t)ordinal);
    return (void*)(uintptr_t)p;
}
static void win_close(void *opaque)
{
    struct WinModule *m=(struct WinModule*)opaque;
    if(!m)return; if(m->h)FreeLibrary(m->h); free(m);
}
#endif

static void module_set(struct Soft386NativeModule *m,const char *label,
                       void *opaque,void *(*get_proc)(void*,uint32_t),
                       void (*close_fn)(void*),int trace)
{
    memset(m,0,sizeof(*m));m->label=label;m->opaque=opaque;m->get_proc=get_proc;
    m->close=close_fn;m->trace=trace;m->loaded=get_proc!=NULL;
}

static int module_open(struct Soft386NativeModule *m,const char *label,
                       const char *path,const char *fallback,int required,int trace)
{
    module_set(m,label,NULL,NULL,NULL,trace);
#ifdef _WIN32
    {
        struct WinModule *wm; HMODULE h; const char *name=(path&&path[0])?path:fallback;
        h=LoadLibraryA(name);
        if(!h){
            if(required)fprintf(stderr,"soft386: cannot load native %s bridge %s (Win32 error %lu)\n",label,name,(unsigned long)GetLastError());
            else if(trace)fprintf(stderr,"soft386: native %s bridge not loaded: %s\n",label,name);
            return 0;
        }
        wm=(struct WinModule*)calloc(1,sizeof(*wm)); if(!wm){FreeLibrary(h);return 0;}
        wm->h=h;module_set(m,label,wm,win_get_proc,win_close,trace);
        if(trace)fprintf(stderr,"soft386: native %s bridge loaded: %s\n",label,name);
        return 1;
    }
#else
    (void)path;(void)fallback;
    if(required)fprintf(stderr,"soft386: native %s bridge is available only on Win32\n",label);
    return 0;
#endif
}

int soft386_system_bridge_open_mask(struct Soft386SystemBridge *b,uint32_t mask,
                               const char *vio_path,int vio_required,
                               const char *kbd_path,int kbd_required,
                               const char *ses_path,int ses_required,int trace)
{
    int ok=1;
    if(!b) return 0;
    memset(b,0,sizeof(*b));
    b->trace=trace;
    if((mask&SOFT386_SYS_VIO)!=0u && !module_open(&b->vio,"VIOCALLS",vio_path,"VIOCALLS.dll",vio_required,trace)&&vio_required)ok=0;
    if((mask&SOFT386_SYS_KBD)!=0u && !module_open(&b->kbd,"KBDCALLS",kbd_path,"KBDCALLS.dll",kbd_required,trace)&&kbd_required)ok=0;
    if((mask&SOFT386_SYS_SES)!=0u && !module_open(&b->ses,"SESMGR",ses_path,"SESMGR.dll",ses_required,trace)&&ses_required)ok=0;
    return ok;
}
int soft386_system_bridge_open(struct Soft386SystemBridge *b,
                               const char *vio_path,int vio_required,
                               const char *kbd_path,int kbd_required,
                               const char *ses_path,int ses_required,int trace)
{
    return soft386_system_bridge_open_mask(b,SOFT386_SYS_ALL,
        vio_path,vio_required,kbd_path,kbd_required,ses_path,ses_required,trace);
}
void soft386_system_bridge_close(struct Soft386SystemBridge *b)
{
    struct Soft386NativeModule *m[3];int i;if(!b)return;m[0]=&b->vio;m[1]=&b->kbd;m[2]=&b->ses;
    for(i=0;i<3;i++){if(m[i]->close&&m[i]->opaque)m[i]->close(m[i]->opaque);memset(m[i],0,sizeof(*m[i]));}
    b->trace=0;
}
int soft386_system_bridge_set_provider(struct Soft386SystemBridge *b,const char *module,
                                       void *opaque,void *(*get_proc)(void*,uint32_t),
                                       void (*close_fn)(void*),int trace)
{
    struct Soft386NativeModule *m;if(!b)return 0;
    if(eqi(module,"VIOCALLS"))m=&b->vio;else if(eqi(module,"KBDCALLS"))m=&b->kbd;
    else if(eqi(module,"SESMGR"))m=&b->ses;else return 0;
    module_set(m,module,opaque,get_proc,close_fn,trace);return 1;
}

static struct Soft386NativeModule *get_module(struct Soft386SystemBridge *b,const char *module)
{
    if(!b) return NULL;
    if(eqi(module,"VIOCALLS")) return &b->vio;
    if(eqi(module,"KBDCALLS")) return &b->kbd;
    if(eqi(module,"SESMGR")) return &b->ses;
    return NULL;
}
static void *proc(struct Soft386NativeModule *m,uint32_t ord)
{return (m&&m->loaded&&m->get_proc)?m->get_proc(m->opaque,ord):NULL;}
static void trace_call(struct Soft386NativeModule *m,uint32_t ord,const char *name)
{if(m&&m->trace)fprintf(stderr,"soft386: native %s.%u %s [marshalled]\n",m->label?m->label:"?",ord,name);}
static uint32_t missing(struct Soft386NativeModule *m,uint32_t ord)
{if(m&&m->trace)fprintf(stderr,"soft386: native %s.%u export missing\n",m->label?m->label:"?",ord);return OS2_ERROR_INVALID_FUNCTION;}
static int need(const struct Soft386GuestMemoryOps *m,uint32_t p,uint32_t cb,int wr)
{return (!p&&cb)?0:m->valid(m->opaque,p,cb,wr);}
static uint16_t ru16(const struct Soft386GuestMemoryOps *m,uint32_t p)
{unsigned char b[2];if(!m->read(m->opaque,p,b,2))return 0;return (uint16_t)(b[0]|((uint16_t)b[1]<<8));}
static uint32_t ru32(const struct Soft386GuestMemoryOps *m,uint32_t p)
{return m->read_u32(m->opaque,p);}
static int wu16(const struct Soft386GuestMemoryOps *m,uint32_t p,uint16_t v)
{unsigned char b[2];b[0]=(unsigned char)v;b[1]=(unsigned char)(v>>8);return m->write(m->opaque,p,b,2);}
static int get_cstr(const struct Soft386GuestMemoryOps *m,uint32_t p,char *s,uint32_t cap)
{return p&&s&&cap&&m->read_cstr(m->opaque,p,s,cap);}
static void *temp_alloc(uint32_t cb){if(cb>BRIDGE_MAX_BUFFER)return NULL;if(!cb)cb=1;return calloc(1,cb);}
#define PCAST(type,p) ((type)(uintptr_t)(p))

