static char *dup_guest_cstr(const struct Soft386GuestMemoryOps *m,uint32_t p)
{char tmp[BRIDGE_MAX_STRING],*r;if(!p)return NULL;if(!get_cstr(m,p,tmp,sizeof(tmp)))return NULL;r=(char*)malloc(strlen(tmp)+1);if(r)strcpy(r,tmp);return r;}
static unsigned char *dup_multisz(const struct Soft386GuestMemoryOps *m,uint32_t p)
{unsigned char *r;uint32_t n=0;unsigned char c=0,prev=1;if(!p)return NULL;r=(unsigned char*)malloc(65536u);if(!r)return NULL;while(n<65536u){if(!m->read(m->opaque,p+n,&c,1)){free(r);return NULL;}r[n++]=c;if(c==0&&prev==0)return r;prev=c;}free(r);return NULL;}
static uint16_t b16(const unsigned char *p){return (uint16_t)(p[0]|((uint16_t)p[1]<<8));}
static uint32_t b32(const unsigned char *p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}

