static unsigned flat_nargs(const char *module,uint32_t ord)
{
    if(eqi(module,"VIOCALLS")){
        switch(ord){case 7:return 7;case 9:return 3;case 13:return 5;case 15:return 3;case 19:return 3;case 21:return 2;case 24:return 5;case 26:return 5;case 27:return 2;case 32:return 2;case 48:return 6;case 52:return 5;default:return 0;}}
    if(eqi(module,"KBDCALLS")){switch(ord){case 4:return 3;case 9:return 4;case 10:case 11:case 22:return 2;case 13:return 1;default:return 0;}}
    if(eqi(module,"SESMGR")){switch(ord){case 5:case 8:return 2;case 17:case 1000:return 3;default:return 0;}}
    return 0;
}

